class Solution {
  public String maxValue(String n, int x) {
    char d = (char) ('0' + x);
    int start = n.charAt(0) == '-' ? 1 : 0;
    if (start == 0) {
      for (int i = 0; i < n.length(); i++)
        if (n.charAt(i) < d) return n.substring(0, i) + d + n.substring(i);
    } else {
      for (int i = 1; i < n.length(); i++)
        if (n.charAt(i) > d) return n.substring(0, i) + d + n.substring(i);
    }
    return n + d;
  }
}
